    font-weight: 700;
}

/* 成功：灯箱黄方灯 */
#toast-container > .toast-success {
    background-color: var(--ds-lamp) !important;
    background-image: var(--ds-lamp-tubes), var(--ds-lamp-box) !important;
    background-position: center !important;
    background-size: auto !important;
    padding-left: 16px !important;
    color: var(--ds-ink);
    box-shadow: var(--ds-lamp-glow), 0 14px 30px rgba(0, 0, 0, 0.45);
