#toast-container > .toast-info {
    background-color: var(--ds-wood) !important;
    background-image: repeating-linear-gradient(92deg, rgba(0, 0, 0, 0.08) 0 7px, rgba(255, 255, 255, 0.04) 7px 15px, rgba(0, 0, 0, 0.12) 15px 19px);
